// Track B doc generation: bid pack (S19; review 06 §3.1). Generated by the NEXT.JS route
// (Chromium per request + execSync python, generate-bid-docs/route.ts:210-283) on spec-Approved
// pre-staged tenders; the route returns 409 otherwise (:364-370). Body = the UI's bid form fields
// (tenders/[id]/page.tsx:291-301, :1405-1408). One distinct tender per bid pack.
import { CFG } from '../lib/config.js';
import { jsonOf, setScreen } from '../lib/http.js';
import * as M from '../lib/metrics.js';
import { uniform } from '../lib/pick.js';
import { dwell } from '../lib/poll.js';
import { detailPoller, openDetail } from './detail.js';
import * as ui from '../lib/ui.js';

function fields(t) {
  return {
    orientation: 'portrait',
    bidNumber: (t && t.ref_no) || 'GEM/2026/B/0000000',
    bidDate: ((t && t.publish_date) || '2026-10-01').split(' ')[0],
    authorityName: (t && t.authority) || 'Authority',
    authorityDept: 'Procurement Department',
    authorityAddress: (t && t.location) || 'India',
    productDescription: (t && t.product_name_as_per_tender) || 'Medical equipment as per tender',
    requiredQuantity: '300',
    companyKey: 'me',
  };
}

export async function bidPackOnce(ctx) {
  const pool = ctx.pools.bidpack;
  const id = pool ? pool.next() : null;
  if (!id) { M.poolExhausted.add(1, { kind: 'bidpack' }); return false; }
  ctx.consumed.add(id);
  const t = await openDetail(id, 'bidpack');
  const dpoll = detailPoller(id, 'bidpack');
  const t0 = Date.now();
  const res = await ui.generateBidDocs(id, fields(t), 'bidpack');
  M.bidpackMs.add(Date.now() - t0);
  const j = jsonOf(res);
  M.bidpackOk.add(res.status === 200 && j && j.success === true);
  await ui.tender(id, 'bidpack');
  await dwell(uniform(ctx.rnd, ...CFG.screens.bidpack.think_between_s) * 1000, [dpoll]);
  dpoll.stop();
  return true;
}

export async function bidPackLoop(ctx, endMs, fallback) {
  setScreen('bidpack');
  while (Date.now() < endMs) {
    const did = await bidPackOnce(ctx);
    if (!did) return fallback(ctx, endMs);
  }
  return null;
}
